import { TriggerDefinition } from '../../TriggerDefinition'
import {
    BooleanColumn,
    ConditionsColumn,
    DocumentIdColumn,
    IntegerColumn,
    ReferenceColumn,
    StringColumn,
    TableNameColumn,
} from '../../../db'

export const inboundEmailTrigger = TriggerDefinition({
    $id: '6f0180400b320300f4eb8bf637673ad4',
    name: 'Inbound Email',
    type: 'email',
    inputs: {
        email_conditions: ConditionsColumn({
            label: 'Email Conditions',
            hint: 'Conditions to qualify which emails start your flow.',
            attributes: {
                condition_builder: 'v2',
            },
            reference: 'sys_email',
            reference_display: 'Email',
        }),
        order: IntegerColumn({
            label: 'Order',
            hint: 'The priority given to the trigger over other inbound email triggers.',
            attributes: {
                visible: 'false',
            },
        }),
        stop_condition_evaluation: BooleanColumn({
            label: 'Stop processing',
            default: true,
            hint: 'When true, processes only the flow with the lowest-value order.',
            attributes: {
                visible: 'false',
            },
        }),
        target_table: TableNameColumn({
            label: 'Reply Record Type',
            hint: 'The table associated with the reply record.',
        }),
    },
    outputs: {
        inbound_email: ReferenceColumn({
            label: 'Inbound Email',
            referenceTable: 'sys_email',
        }),
        target_table_name: TableNameColumn({
            label: 'Target Table Name',
            maxLength: 255,
        }),
        body_text: StringColumn({
            label: 'Body Text',
            isFullUTF8: true,
            maxLength: 255,
        }),
        subject: StringColumn({
            label: 'Subject',
            isFullUTF8: true,
            maxLength: 255,
        }),
        user: ReferenceColumn({
            label: 'User',
            referenceTable: 'sys_user',
        }),
        target_record: DocumentIdColumn({
            dependent: 'target_table_name',
            label: 'Target Record',
            maxLength: 255,
        }),
        from_address: StringColumn({
            label: 'From address',
            isFullUTF8: true,
            maxLength: 255,
        }),
    },
})
